import MathFin.Pricing.FTAP.DensityPasting

open MeasureTheory
open MathFin

/-- One-period densities paste to an equivalent martingale measure. -/
theorem density_pasting_isEMM {Ω : Type*} {m0 : MeasurableSpace Ω} {F : Type*}
    [NormedAddCommGroup F] [InnerProductSpace ℝ F] [CompleteSpace F] {𝓕 : Filtration ℕ m0}
    {P : Measure Ω} [IsProbabilityMeasure P] {S : ℕ → Ω → F} {T : ℕ} {Z : ℕ → Ω → ℝ}
    (h : LocalEMMDensities 𝓕 P S T Z) : IsEMM 𝓕 P S T (pastedMeasure P Z T) :=
  h.isEMM_pastedMeasure
